package exercise.funcionario.domain;public class Funcionario {    public String nome;    public int idade;    public double[] salario = new double[3];    public void imprime () {        System.out.println(this.nome);        System.out.println(this.idade);        System.out.println(this.salario);    }    public void mediaSalario (){        double soma = 0;              for (double s : salario){            soma += s;        }        double media = (salario[0] + salario[1] + salario[2]) / 3;        System.out.println("A soma dos salarios dá: " + soma + "R$");        System.out.printf("A média dos salarios dá:  %f R$", media);    }}